<?php
require_once 'db_connect.php';session_start();if(($_SESSION['user_role']??'')!=='admin'){header('Location: admin-login.php');exit;}
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';$allowed=['Scheduled','In Progress','Completed','Delivered'];if($id&&in_array($status,$allowed,true)){$st=$conn->prepare("UPDATE appointments SET status=? WHERE id=?");$st->bind_param('si',$status,$id);$st->execute();$msg=$st->affected_rows>=0?'Appointment status update processed.':'Unable to update appointment.';$st->close();}else{$msg='Invalid appointment ID or status.';}}
$total=(int)($conn->query("SELECT COUNT(*) c FROM appointments")->fetch_assoc()['c']??0);$scheduled=(int)($conn->query("SELECT COUNT(*) c FROM appointments WHERE status='Scheduled'")->fetch_assoc()['c']??0);$progress=(int)($conn->query("SELECT COUNT(*) c FROM appointments WHERE status='In Progress'")->fetch_assoc()['c']??0);$rows=$conn->query("SELECT id,customer_name,email,vehicle,service_name,service_date,status FROM appointments ORDER BY id DESC");function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Admin Dashboard</h1><p>Vehicle Service Management · Administration</p></header><nav class="navbar"><a href="index.php">Public Website</a><a href="admin-dashboard.php">Dashboard</a><a href="logout.php">Logout</a></nav><main><section class="panel"><h2>Overview</h2><div class="cards"><div class="stat">Total appointments<strong><?=e($total)?></strong></div><div class="stat">Scheduled<strong><?=e($scheduled)?></strong></div><div class="stat">In progress<strong><?=e($progress)?></strong></div></div></section><section class="panel"><h2>Manage Appointment Status</h2><?php if($msg):?><p class="notice"><?=e($msg)?></p><?php endif;?><p>Use the appointment ID from the table.</p><form method="post"><label>Appointment ID<input type="number" name="id" min="1" required></label><label>Status<select name="status" required><option>Scheduled</option><option>In Progress</option><option>Completed</option><option>Delivered</option></select></label><button type="submit">Update Status</button></form></section><section class="panel"><h2>All Appointments</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Customer</th><th>Email</th><th>Vehicle</th><th>Service</th><th>Date</th><th>Status</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['id'])?></td><td><?=e($r['customer_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['vehicle'])?></td><td><?=e($r['service_name'])?></td><td><?=e($r['service_date'])?></td><td><?=e($r['status'])?></td></tr><?php endwhile;else:?><tr><td colspan="7">No appointments found.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
